function validate([m, n, introvertsCount, extrovertsCount]) {
  const whole = v => Number.isInteger(v);
  if (!whole(m) || !whole(n) || m < 1 || m > 5 || n < 1 || n > 5) return 'm and n are whole numbers from 1 to 5.';
  const most = Math.min(m * n, 6);
  if (!whole(introvertsCount) || introvertsCount < 0 || introvertsCount > most) return 'introvertsCount is from 0 to min(m * n, 6).';
  if (!whole(extrovertsCount) || extrovertsCount < 0 || extrovertsCount > most) return 'extrovertsCount is from 0 to min(m * n, 6).';
  return null;
}

