function getMaxGridHappiness(m, n, introvertsCount, extrovertsCount) {
  const cells = m * n;
  const top = 3 ** (n - 1);
  const effect = [0, -30, 20];
  const memo = new Array(cells * 243 * 49).fill(-1);
  const pairGain = (mine, other) => (other === 0 ? 0 : effect[mine] + effect[other]);

  function best(pos, profile, intro, extro) {
    if (pos === cells || intro + extro === 0) return 0;
    const key = ((pos * 243 + profile) * 7 + intro) * 7 + extro;
    if (memo[key] !== -1) return memo[key];
    const up = Math.floor(profile / top);
    const left = pos % n > 0 ? profile % 3 : 0;
    const shifted = (profile % top) * 3;
    let result = best(pos + 1, shifted, intro, extro);
    if (intro > 0) {
      const gain = 120 + pairGain(1, up) + pairGain(1, left);
      result = Math.max(result, gain + best(pos + 1, shifted + 1, intro - 1, extro));
    }
    if (extro > 0) {
      const gain = 40 + pairGain(2, up) + pairGain(2, left);
      result = Math.max(result, gain + best(pos + 1, shifted + 2, intro, extro - 1));
    }
    memo[key] = result;
    return result;
  }

  return best(0, 0, introvertsCount, extrovertsCount);
}

