function getMaxGridHappiness(m, n, introvertsCount, extrovertsCount) {
  const grid = Array.from({ length: m }, () => new Array(n).fill(0));
  let answer = 0;
  const score = () => {
    let total = 0;
    for (let r = 0; r < m; r++)
      for (let c = 0; c < n; c++) {
        if (grid[r][c] === 0) continue;
        let around = 0;
        for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const rr = r + dr, cc = c + dc;
          if (rr >= 0 && rr < m && cc >= 0 && cc < n && grid[rr][cc] !== 0) around++;
        }
        total += grid[r][c] === 1 ? 120 - 30 * around : 40 + 20 * around;
      }
    return total;
  };
  const place = (cell, introLeft, extroLeft) => {
    if (cell === m * n) { answer = Math.max(answer, score()); return; }
    const r = Math.floor(cell / n), c = cell % n;
    place(cell + 1, introLeft, extroLeft);
    if (introLeft > 0) { grid[r][c] = 1; place(cell + 1, introLeft - 1, extroLeft); grid[r][c] = 0; }
    if (extroLeft > 0) { grid[r][c] = 2; place(cell + 1, introLeft, extroLeft - 1); grid[r][c] = 0; }
  };
  place(0, introvertsCount, extrovertsCount);
  return answer;
}

