function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  let m, n;
  if (size === 'large') {
    m = 4 + pick(2);
    n = 4 + pick(2);
  } else {
    do { m = 1 + pick(4); n = 1 + pick(4); } while (m * n > 9);
  }
  const most = Math.min(m * n, 6);
  const count = () => size === 'large' && rand() < 0.6 ? most : pick(most + 1);
  return [m, n, count(), count()];
}
